# RW4DM_DRAWORDER: BringToFront, SendToBack, BringForward, SendBackward, ClearDrawOrder: the draw order levels. The script rw4dm_draworder_script.txt is generated by rw4dm_gen.py. The oracle is exact set / string logic on four objects (ids 1..4 = Point, Line, Plane, Box):
# after each step the objects that List reaches are compared, as id:kind:layer[:name], with the expected list exactly (and the printed message lines with their patterns).
RW4_DRAWORDER_OUT=""
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RW4_DRAWORDER_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rw4dm_draworder_script.txt" 2>&1)" || { echo "$RW4_DRAWORDER_OUT" | tail -40; echo "FAIL RW4DM_DRAWORDER_run: script exited non-zero"; fail=1; RW4_DRAWORDER_OUT=""; }
else
  RW4_DRAWORDER_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rw4dm_draworder_script.txt" 2>&1)" || { echo "$RW4_DRAWORDER_OUT" | tail -40; echo "FAIL RW4DM_DRAWORDER_run: script exited non-zero"; fail=1; RW4_DRAWORDER_OUT=""; }
fi
rw4_draworder_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW4BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW4BEGIN_/ { exit } on { print }' <<<"$RW4_DRAWORDER_OUT"; }
# rw4_draworder_state STEP EXPECTED DESC [PATTERN...]: the objects listed in the step read exactly EXPECTED ("-" = none); each PATTERN must match a printed line of the step
rw4_draworder_state() {
  local blk got name desc pat bad want; name="$1"; want="$2"; desc="$3"; blk="$(rw4_draworder_block "$name")"
  got="$({ grep -E '^history: Object [0-9]+ \(' <<<"$blk" || true; } | sed -E "s/^history: Object ([0-9]+) \(([^)]*)\) layer (.*) name '(.*)'\$/\1:\2:\3:\4/; s/^history: Object ([0-9]+) \(([^)]*)\) layer (.*)\$/\1:\2:\3/" | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  bad=""
  shift 3
  for pat in "$@"; do grep -qE "^history: $pat" <<<"$blk" || bad="$bad [$pat]"; done
  if [ "$got" = "$want" ] && [ -z "$bad" ]; then echo "ok   RW4DM_DRAWORDER_$name: $desc (objects: $got)"
  else echo "FAIL RW4DM_DRAWORDER_$name: $desc (listed '$got', expected '$want'; missing message patterns:${bad:- none})"; fail=1; { grep -E '^history: (Object|!|[A-Za-z]+:)' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}

# rw4_draworder_lines STEP REGEX SED EXPECTED DESC SORTFLAG TAG: the lines of the step that match "history: REGEX", with "history: " removed and SED applied, joined by " | " (sorted
# bytewise first when the sixth argument is "sort"), read exactly EXPECTED ("-" = no line)
rw4_draworder_lines() {
  local blk got; blk="$(rw4_draworder_block "$1")"
  got="$({ grep -E "^history: $2" <<<"$blk" || true; } | sed -E 's/^history: //' | sed -E "$3" | { if [ "${6:-}" = sort ]; then LC_ALL=C sort; else cat; fi; } | paste -sd'|' - | sed 's/|/ | /g')"; [ -n "$got" ] || got="-"
  if [ "$got" = "$4" ]; then echo "ok   RW4DM_DRAWORDER_$1_${7:-lines}: $5 (lines: $got)"
  else echo "FAIL RW4DM_DRAWORDER_$1_${7:-lines}: $5 (got '$got', expected '$4')"; fail=1; { grep -E '^history: ' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}

# rw4_draworder_rank BLOCK ID: the DrawOrder printed for the object by GetUserText (0 when it carries none: the default level)
rw4_draworder_rank() { local v; v="$({ grep -E "^history: $2: DrawOrder = " <<<"$1" || true; } | sed -E 's/.*= (-?[0-9]+)$/\1/' | head -1)"; echo "${v:-0}"; }
# rw4_draworder_order STEP KIND SUBJECT DESC: front: SUBJECT ends strictly above every other object; back: strictly below every other; forward / backward: exactly one level
# up / down from where it was; clear: it carries no DrawOrder any more. In every case no other object changed level.
rw4_draworder_order() {
  local name="$1" kind="$2" x="$3" desc="$4" b a ok=1 id ra rb xa xb hi=-999999 lo=999999
  b="$(rw4_draworder_block "${name}_before")"; a="$(rw4_draworder_block "$name")"
  for id in 1 2 3 4; do
    ra="$(rw4_draworder_rank "$a" $id)"; rb="$(rw4_draworder_rank "$b" $id)"
    if [ "$id" != "$x" ]; then
      [ "$ra" = "$rb" ] || ok=0
      if [ "$ra" -gt "$hi" ]; then hi=$ra; fi
      if [ "$ra" -lt "$lo" ]; then lo=$ra; fi
    fi
  done
  xa="$(rw4_draworder_rank "$a" $x)"; xb="$(rw4_draworder_rank "$b" $x)"
  case "$kind" in
    front) [ "$xa" -gt "$hi" ] || ok=0;;
    back) [ "$xa" -lt "$lo" ] || ok=0;;
    forward) [ "$xa" = "$((xb + 1))" ] || ok=0;;
    backward) [ "$xa" = "$((xb - 1))" ] || ok=0;;
    clear) if grep -qE "^history: $x: DrawOrder" <<<"$a"; then ok=0; fi;;
  esac
  if [ "$ok" = 1 ]; then echo "ok   RW4DM_DRAWORDER_$name: $desc (level of $x: $xb -> $xa; others $(for id in 1 2 3 4; do [ "$id" = "$x" ] || printf '%s ' "$(rw4_draworder_rank "$a" $id)"; done)unchanged)"
  else echo "FAIL RW4DM_DRAWORDER_$name: $desc (level of $x: $xb -> $xa, highest other $hi, lowest other $lo, others changed: $([ "$ok" = 1 ] && echo no || echo maybe))"; fail=1; { grep -E '^history: [0-9]+: ' <<<"$b" || true; } | sed 's/^/     before: /'; { grep -E '^history: [0-9]+: ' <<<"$a" || true; } | sed 's/^/     after: /'; fi
}
rw4_draworder_order front1 front 3 "BringToFront of object 3 puts it in front of all others, nothing else moves"
rw4_draworder_order front2 front 1 "a second BringToFront (object 1) goes in front of 3 as well"
rw4_draworder_order back1 back 4 "SendToBack of object 4 puts it behind all others"
rw4_draworder_order forward forward 2 "BringForward of object 2 moves it exactly one level up"
rw4_draworder_order backward backward 1 "SendBackward of object 1 moves it exactly one level down"
rw4_draworder_order back2 back 2 "SendToBack of object 2 puts it behind everything, below the earlier back object 4"
rw4_draworder_order clear1 clear 3 "ClearDrawOrder of object 3 removes its level, the others keep theirs"
rw4_draworder_lines clearall "[0-9]+: DrawOrder = " "s/x/x/" "-" "after ClearDrawOrder on everything no object carries a DrawOrder" nosort lines
